// The launcher the plugin ships as plugin/dist/run, generated by scripts/launcher.mjs: it maps the first
// argument to its entry and runs it on the installed huddle binary, which the launcher itself downloads and
// checksum-verifies on first use of any entry. There is no JS fallback: with no binary available and none
// downloadable the launcher says why and exits 127, and a hook — huddle's own `hook <name>`, radar's
// `radar hook` or kanban's `kanban hook session-start` — exits 0 silently, starting one detached download
// whose lock lives in the version dir. Downloads go to a local server through HUDDLE_DOWNLOAD_BASE; nothing
// here touches the network. Run with `node --test scripts/launcher.test.mjs`.
import { spawn, spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import {
  chmodSync,
  existsSync,
  mkdirSync,
  mkdtempSync,
  readdirSync,
  readFileSync,
  realpathSync,
  rmSync,
  statSync,
  symlinkSync,
  writeFileSync,
} from "node:fs";
import { createServer } from "node:http";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { huddleSpec, launcherScript, releaseInfo } from "./launcher.mjs";

/** The release a build embeds in the launcher (releaseInfo's shape). */
const RELEASE = {
  version: "9.9.9",
  repo: "MuhmdRaouf/huddle",
  sha256: {},
};

/** One run of the launcher: its exit status and its output. */
function ran(status, stdout, stderr) {
  return { status, stdout, stderr };
}

/** The fake binary asset the tests serve and install: a shell script printing its name and arguments. */
const asset = (name) => `#!/bin/sh\necho ${name} "$@"\n`;

/** This machine's platform as the launcher computes it, so the served digest matches the embedded one. */
const PLATFORMS = { darwin: "darwin", linux: "linux" };
const ARCHES = { arm64: "arm64", x64: "amd64" };
const OS = PLATFORMS[process.platform] ?? "unsupported";
const ARCH = ARCHES[process.arch] ?? "unsupported";

/** Every external tool the launcher may call; the rig symlinks each one the machine has into its tools dir. */
const TOOLS = [
  "chmod",
  "curl",
  "date",
  "dirname",
  "mkdir",
  "mv",
  "openssl",
  "rm",
  "sha256sum",
  "sh",
  "shasum",
  "sleep",
  "uname",
  "wget",
];

/** The one flavour of the launcher: how dist/run is rendered, and the names it installs and calls. */
const HUDDLE = {
  render: (release) => launcherScript(huddleSpec(release)),
  homeEnv: "AGENTS_HUDDLE_HOME",
  baseEnv: "HUDDLE_DOWNLOAD_BASE",
  binary: "huddle",
  lock: ".huddle.fetch.lock",
};

/** The release info for a manifest whose one asset targets this platform; `digest` overrides the asset's
 *  real one. The fake asset matches the binary's name, so its checksum is what lands. */
function info(digest = createHash("sha256").update(asset(HUDDLE.binary)).digest("hex")) {
  return { ...RELEASE, sha256: { [`${OS}-${ARCH}`]: digest } };
}

/**
 * A dist dir with the launcher and a bin dir holding fake runtimes that print their name and arguments. The
 * external tools the launcher needs are symlinked into a tools dir (whichever checksum tool and downloader
 * the machine has); /usr/bin itself may hold a node (some CI images), so it stays off PATH. `t` owns the
 * temp dir: everything is removed when the test finishes.
 */
function rig(t, release, runtimes = [], uname) {
  const dir = realpathSync(mktemp("launcher-"));
  const dist = join(dir, "dist");
  const bin = join(dir, "bin");
  const tools = join(dir, "tools");
  mkdirSync(dist);
  mkdirSync(bin);
  mkdirSync(tools);
  for (const tool of TOOLS) {
    const real = spawnSync("/bin/sh", ["-c", `command -v ${tool}`], { encoding: "utf8" }).stdout.trim();
    if (real !== "") symlinkSync(real, join(tools, tool));
  }
  writeFileSync(join(dist, "run"), HUDDLE.render(release));
  for (const name of runtimes) {
    writeFileSync(join(bin, name), `#!/bin/sh\necho ${name} "$@"\n`);
    chmodSync(join(bin, name), 0o755);
  }
  if (uname !== undefined) {
    writeFileSync(join(bin, "uname"), `#!/bin/sh\necho ${uname}\n`);
    chmodSync(join(bin, "uname"), 0o755);
  }
  const binHome = join(dir, "bin-home");
  // Spawned, not spawnSync: a sync spawn would block this process's event loop and with it the asset server a
  // download test serves its fake binary from.
  const run = (args, env = {}) =>
    new Promise((resolve) => {
      const child = spawn("/bin/sh", [join(dist, "run"), ...args], {
        env: { PATH: `${bin}:${tools}`, HOME: join(dir, "home"), [HUDDLE.homeEnv]: binHome, ...env },
      });
      let stdout = "";
      let stderr = "";
      child.stdout.on("data", (chunk) => (stdout += chunk));
      child.stderr.on("data", (chunk) => (stderr += chunk));
      child.on("close", (status) => resolve(ran(status, stdout, stderr)));
    });
  t.after(() => rmSync(dir, { recursive: true, force: true }));
  return { dir, dist, bin, binHome, lock: join(binHome, RELEASE.version, HUDDLE.lock), run };
}

/** A fresh directory under the system temp dir, removed by the caller. */
function mktemp(prefix) {
  return mkdtempSync(join(tmpdir(), prefix));
}

/** A server answering every request with `body`; resolves with its base URL and every path it was asked for. */
async function assetServer(t, body) {
  const urls = [];
  const server = createServer((request, response) => {
    urls.push(request.url ?? "");
    response.end(body);
  });
  await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
  const port = server.address().port;
  t.after(() => server.close());
  return { base: `http://127.0.0.1:${port}`, urls };
}

/** An installed binary the launcher execs: the fake asset, executable, under the home/<version>. */
function install(binHome) {
  const bin = join(binHome, RELEASE.version, `${HUDDLE.binary}`);
  mkdirSync(dirname(bin), { recursive: true });
  writeFileSync(bin, asset(HUDDLE.binary));
  chmodSync(bin, 0o755);
  return bin;
}

/** A curl first on PATH that logs its arguments to $CURL_LOG and fails, so a test proves the timeout the
 *  launcher picked without touching the network. Returns the log's path. */
function failingCurl(bin) {
  writeFileSync(join(bin, "curl"), '#!/bin/sh\nprintf \'%s\\n\' "$*" >> "$CURL_LOG"\nexit 22\n');
  chmodSync(join(bin, "curl"), 0o755);
  return join(dirname(bin), "curl.log");
}

/** Resolve true once `probe` passes, or false after `ms` (50 ms steps). */
async function until(probe, ms) {
  const deadline = Date.now() + ms;
  while (!probe()) {
    if (Date.now() >= deadline) return false;
    await new Promise((resolve) => setTimeout(resolve, 50));
  }
  return true;
}

/** A fetch lock in the version dir holding `content`, as a detached download writes "<pid> <epoch seconds>". */
function writeLock(binHome, content) {
  const dir = join(binHome, RELEASE.version);
  mkdirSync(dir, { recursive: true });
  writeFileSync(join(dir, HUDDLE.lock), `${content}\n`);
}

describe("dist/run", () => {
  it("renders the committed launcher byte for byte from the newest manifest", () => {
    const release = releaseInfo(join(import.meta.dirname, "../release"));
    const committed = readFileSync(join(import.meta.dirname, "../plugin/dist/run"), "utf8");
    assert.equal(launcherScript(huddleSpec(release)), committed);
  });

  it("pins the tag, the release URL and the versioned bin home of the committed manifest", () => {
    const release = releaseInfo(join(import.meta.dirname, "../release"));
    assert.equal(release.version, "0.0.1");
    const script = launcherScript(huddleSpec(release));
    assert.ok(
      script.includes("base=${HUDDLE_DOWNLOAD_BASE:-https://github.com/MuhmdRaouf/huddle/releases/download}"),
      "the release base is the huddle repository's",
    );
    assert.ok(script.includes("url=$base/v0.0.1/huddle-$os-$arch"), "the asset path names tag v0.0.1");
    assert.ok(
      script.includes("home=${AGENTS_HUDDLE_HOME:-$HOME/.agents/huddle-bin}"),
      "the binary home is AGENTS_HUDDLE_HOME or .agents/huddle-bin",
    );
    assert.ok(script.includes("bin=$home/0.0.1/huddle"), "the installed binary is the huddle binary");
  });

  it("maps only darwin and linux, and asset names end with the arch", () => {
    const release = {
      ...RELEASE,
      sha256: { "darwin-amd64": "aa", "darwin-arm64": "bb", "linux-amd64": "cc", "linux-arm64": "dd" },
    };
    const script = launcherScript(huddleSpec(release));
    assert.ok(script.includes("Darwin) os=darwin"), "darwin is mapped");
    assert.ok(script.includes("Linux) os=linux"), "linux is mapped");
    const mapped = new Set([...script.matchAll(/\) os=(\w+)/g)].map((m) => m[1]));
    assert.deepEqual(
      [...mapped].filter((os) => os !== "unsupported").sort(),
      ["darwin", "linux"],
      "only darwin and linux are mapped",
    );
    assert.ok(!/suffix/.test(script), "asset names carry no suffix");
  });

  it("runs the installed huddle binary with the word and every argument", async (t) => {
    const { binHome, run } = rig(t, info());
    install(binHome);
    assert.deepEqual(await run(["setup", "--start"]), ran(0, "huddle setup --start\n", ""));
    assert.deepEqual(await run(["hook", "session-start"]), ran(0, "huddle hook session-start\n", ""));
    // the cli entry adds no word of its own: the CLI word follows it (bin/huddle calls it)
    assert.deepEqual(await run(["cli", "open", "--json"]), ran(0, "huddle open --json\n", ""));
    // the satellite words: radar's and kanban's command lines run inside the one binary
    assert.deepEqual(await run(["radar", "start", "--port", "1899"]), ran(0, "huddle radar start --port 1899\n", ""));
    assert.deepEqual(await run(["kanban", "list", "in-progress", "--json"]), ran(0, "huddle kanban list in-progress --json\n", ""));
    assert.deepEqual(await run(["kanban", "--version"]), ran(0, "huddle kanban --version\n", ""));
  });

  it("a command with no binary downloads, checksum-verifies, installs (mode 755) and runs huddle", async (t) => {
    const { binHome, run } = rig(t, info());
    const { base, urls } = await assetServer(t, asset("huddle"));
    const result = await run(["serve"], { HUDDLE_DOWNLOAD_BASE: base });
    assert.equal(result.status, 0);
    assert.equal(result.stderr, "");
    assert.equal(result.stdout, "huddle serve\n");
    assert.deepEqual(urls, [`/v9.9.9/huddle-${OS}-${ARCH}`]);
    const bin = join(binHome, "9.9.9", "huddle");
    assert.equal(readFileSync(bin, "utf8"), asset("huddle"));
    assert.equal(statSync(bin).mode & 0o777, 0o755);
    assert.deepEqual(readdirSync(join(binHome, "9.9.9")), ["huddle"]);
  });

  it("mcp downloads in the foreground with 60 s, says one line and exits 1 when it cannot", async (t) => {
    const { bin, run } = rig(t, info());
    const log = failingCurl(bin);
    const result = await run(["mcp"], { CURL_LOG: log });
    assert.equal(result.status, 1);
    assert.equal(result.stdout, "");
    assert.ok(readFileSync(log, "utf8").includes("--max-time 60 -o"));
    assert.equal(
      result.stderr,
      `huddle: could not download huddle 9.9.9 (https://github.com/MuhmdRaouf/huddle` +
        `/releases/download/v9.9.9/huddle-${OS}-${ARCH})\n`,
    );
  });

  it("a plain command downloads with the long timeout and exits 127 when it cannot", async (t) => {
    const { bin, run } = rig(t, info());
    const log = failingCurl(bin);
    const result = await run(["serve"], { CURL_LOG: log });
    assert.equal(result.status, 127);
    assert.ok(readFileSync(log, "utf8").includes("--max-time 120 -o"));
  });

  it("a checksum mismatch installs nothing: a command exits 127, mcp exits 1", async (t) => {
    const { binHome, run } = rig(t, info("deadbeef".repeat(8)));
    const { base } = await assetServer(t, asset("huddle"));
    const command = await run(["serve"], { HUDDLE_DOWNLOAD_BASE: base });
    assert.equal(command.status, 127);
    assert.equal(command.stderr, "huddle: huddle download failed its checksum\n");
    const mcp = await run(["mcp"], { HUDDLE_DOWNLOAD_BASE: base });
    assert.equal(mcp.status, 1);
    assert.equal(mcp.stderr, "huddle: huddle download failed its checksum\n");
    assert.deepEqual(readdirSync(join(binHome, "9.9.9")), []);
  });

  it("a download that cannot reach the server prints one line with the URL: a command exits 127, mcp 1", async (t) => {
    const { run } = rig(t, info());
    const command = await run(["serve"], { HUDDLE_DOWNLOAD_BASE: "http://127.0.0.1:1" });
    assert.equal(command.status, 127);
    assert.equal(command.stdout, "");
    assert.ok(
      command.stderr.includes(
        `huddle: could not download huddle 9.9.9 (http://127.0.0.1:1/v9.9.9/huddle-${OS}-${ARCH})\n`,
      ),
      `stderr says the URL: ${command.stderr}`,
    );
    const mcp = await run(["mcp"], { HUDDLE_DOWNLOAD_BASE: "http://127.0.0.1:1" });
    assert.equal(mcp.status, 1);
  });

  it("a hook never blocks: every spelling exits 0 within 1 s and one detached download installs the binary", async (t) => {
    // huddle's own hooks (`hook <name>`), radar's (`radar hook`) and kanban's (`kanban hook session-start`)
    for (const args of [
      ["hook", "session-start"],
      ["radar", "hook"],
      ["kanban", "hook", "session-start"],
    ]) {
      await t.test(`${args.join(" ")} returns at once`, async (t) => {
        const { binHome, run, lock } = rig(t, info());
        const { base, urls } = await assetServer(t, asset("huddle"));
        const started = Date.now();
        const first = await run(args, { HUDDLE_DOWNLOAD_BASE: base });
        assert.ok(Date.now() - started < 1000, `the hook returned in ${Date.now() - started} ms`);
        assert.deepEqual(first, ran(0, "", ""));
        const dir = join(binHome, "9.9.9");
        const bin = join(dir, "huddle");
        assert.ok(
          await until(() => existsSync(bin) && !existsSync(lock), 10_000),
          "the detached download lands the verified binary",
        );
        assert.equal(readFileSync(bin, "utf8"), asset("huddle"));
        assert.equal(statSync(bin).mode & 0o777, 0o755);
        assert.deepEqual(readdirSync(dir), ["huddle"]);
        const second = await run(args, { HUDDLE_DOWNLOAD_BASE: base });
        assert.deepEqual(second, ran(0, `huddle ${args.join(" ")}\n`, ""));
        assert.deepEqual(urls, [`/v9.9.9/huddle-${OS}-${ARCH}`]);
      });
    }
  });

  it("two concurrent hooks of different parts start one download between them", async (t) => {
    const { binHome, run, lock } = rig(t, info());
    const { base, urls } = await assetServer(t, asset("huddle"));
    const hooks = await Promise.all([
      run(["hook", "listen"], { HUDDLE_DOWNLOAD_BASE: base }),
      run(["radar", "hook"], { HUDDLE_DOWNLOAD_BASE: base }),
      run(["kanban", "hook", "session-start"], { HUDDLE_DOWNLOAD_BASE: base }),
    ]);
    for (const hook of hooks) assert.deepEqual(hook, ran(0, "", ""));
    const bin = join(binHome, "9.9.9", "huddle");
    assert.ok(
      await until(() => existsSync(bin) && !existsSync(lock), 10_000),
      "one download installs the binary",
    );
    assert.deepEqual(urls, [`/v9.9.9/huddle-${OS}-${ARCH}`]);
  });

  it("a detached download that fails its checksum leaves no binary and no lock behind", async (t) => {
    const { binHome, run } = rig(t, info("deadbeef".repeat(8)));
    const { base, urls } = await assetServer(t, asset("huddle"));
    assert.deepEqual(await run(["radar", "hook"], { HUDDLE_DOWNLOAD_BASE: base }), ran(0, "", ""));
    assert.ok(await until(() => urls.length > 0, 10_000), "the detached fetch reaches the server");
    const dir = join(binHome, "9.9.9");
    assert.ok(
      await until(() => existsSync(dir) && readdirSync(dir).length === 0, 10_000),
      "no lock, binary or temp file is left behind",
    );
  });

  it("a fetch lock whose holder is dead is taken over by the next hook", async (t) => {
    const { binHome, run } = rig(t, info());
    const { base, urls } = await assetServer(t, asset("huddle"));
    const dead = spawn("/bin/sh", ["-c", "exit 0"]);
    await new Promise((resolve) => dead.on("close", resolve));
    writeLock(binHome, `${dead.pid} ${Math.floor(Date.now() / 1000)}`);
    assert.deepEqual(await run(["hook", "report"], { HUDDLE_DOWNLOAD_BASE: base }), ran(0, "", ""));
    assert.ok(
      await until(() => existsSync(join(binHome, "9.9.9", "huddle")), 10_000),
      "the hook's fetch takes over the dead lock",
    );
    assert.deepEqual(urls, [`/v9.9.9/huddle-${OS}-${ARCH}`]);
  });

  it("a fetch lock held by a live, fresh holder starts no second download", async (t) => {
    const { binHome, run } = rig(t, info());
    const { base, urls } = await assetServer(t, asset("huddle"));
    writeLock(binHome, `${process.pid} ${Math.floor(Date.now() / 1000)}`);
    assert.deepEqual(await run(["hook", "report"], { HUDDLE_DOWNLOAD_BASE: base }), ran(0, "", ""));
    await new Promise((resolve) => setTimeout(resolve, 500));
    assert.deepEqual(urls, []);
    assert.equal(existsSync(join(binHome, "9.9.9", "huddle")), false);
  });

  it("a fetch lock older than 120 s is taken over even though its holder lives", async (t) => {
    const { binHome, run } = rig(t, info());
    const { base, urls } = await assetServer(t, asset("huddle"));
    writeLock(binHome, `${process.pid} ${Math.floor(Date.now() / 1000) - 121}`);
    assert.deepEqual(await run(["hook", "report"], { HUDDLE_DOWNLOAD_BASE: base }), ran(0, "", ""));
    assert.ok(
      await until(() => existsSync(join(binHome, "9.9.9", "huddle")), 10_000),
      "the stale lock does not stop the fetch",
    );
    assert.deepEqual(urls, [`/v9.9.9/huddle-${OS}-${ARCH}`]);
  });

  it("with no binary and no server: a hook exits 0 silently, a command exits 127 saying the URL", async (t) => {
    const { binHome, run } = rig(t, info());
    const dead = "http://127.0.0.1:1";
    assert.deepEqual(await run(["radar", "hook"], { HUDDLE_DOWNLOAD_BASE: dead }), ran(0, "", ""));
    const command = await run(["kanban", "list"], { HUDDLE_DOWNLOAD_BASE: dead });
    assert.equal(command.status, 127);
    assert.ok(
      command.stderr.includes(`huddle: could not download huddle 9.9.9 (${dead}/v9.9.9/huddle-${OS}-${ARCH})\n`),
      `stderr says the URL: ${command.stderr}`,
    );
    assert.equal(existsSync(join(binHome, "9.9.9", "huddle")), false);
  });

  it("never runs a JS bundle beside it, whatever runtime is on PATH", async (t) => {
    const { dist, run } = rig(t, info(), ["bun", "node"]);
    const result = await run(["cli", "board"], { HUDDLE_DOWNLOAD_BASE: "http://127.0.0.1:1" });
    assert.equal(result.status, 127);
    assert.equal(result.stdout, "");
    assert.notEqual(result.stdout, `bun ${join(dist, "huddle.js")} board\n`);
  });

  it("an unknown word exits 2 naming it", async (t) => {
    const { binHome, run } = rig(t, info());
    install(binHome);
    const result = await run(["bogus"]);
    assert.equal(result.status, 2);
    assert.equal(result.stderr, "huddle: unknown command bogus\n");
  });

  it("an unsupported platform downloads nothing: a hook exits 0, a command says so and exits 127", async (t) => {
    const { bin, run } = rig(t, info(), [], "Foonix");
    const log = failingCurl(bin);
    const hook = await run(["kanban", "hook", "session-start"], { CURL_LOG: log });
    assert.deepEqual(hook, ran(0, "", ""));
    const command = await run(["serve"], { CURL_LOG: log });
    assert.equal(command.status, 127);
    assert.equal(command.stderr, "huddle: no huddle 9.9.9 binary for this platform (unsupported-unsupported)\n");
    assert.equal(existsSync(log), false);
  });

  it("huddleSpec refuses to generate a launcher with no release to pin", () => {
    assert.throws(() => huddleSpec(null), /no huddle release/);
  });
});

describe("releaseInfo", () => {
  it("reads the newest manifest by semver and maps its assets to digests", (t) => {
    const dir = mktemp("launcher-release-");
    t.after(() => rmSync(dir, { recursive: true, force: true }));
    writeFileSync(
      join(dir, "v0.9.0.json"),
      JSON.stringify({
        version: "0.9.0",
        tag: "v0.9.0",
        assets: { "linux-amd64": { name: "huddle-linux-amd64", sha256: "cafe00", size: 1 } },
      }),
    );
    writeFileSync(
      join(dir, "v0.10.0.json"),
      JSON.stringify({
        version: "0.10.0",
        tag: "v0.10.0",
        assets: {
          "darwin-arm64": { name: "huddle-darwin-arm64", sha256: "abcd00", size: 2 },
          "linux-amd64": { name: "huddle-linux-amd64", sha256: "beef00", size: 3 },
        },
      }),
    );
    writeFileSync(join(dir, "notes.txt"), "not a manifest");
    assert.deepEqual(releaseInfo(dir), {
      version: "0.10.0",
      repo: "MuhmdRaouf/huddle",
      sha256: { "darwin-arm64": "abcd00", "linux-amd64": "beef00" },
    });
  });

  it("is null while no release manifest exists", (t) => {
    const dir = mktemp("launcher-release-");
    t.after(() => rmSync(dir, { recursive: true, force: true }));
    assert.equal(releaseInfo(join(dir, "none")), null);
    assert.equal(releaseInfo(dir), null);
    writeFileSync(join(dir, "v0.1.0.txt"), "{}");
    assert.equal(releaseInfo(dir), null);
  });
});
